package com.example.dsatracker.mapper;import com.example.dsatracker.dto.ProblemRequestDTO;import com.example.dsatracker.dto.ProblemResponseDTO;import com.example.dsatracker.dto.TagResponseDTO;import com.example.dsatracker.model.Problem;import com.example.dsatracker.model.Tag;import java.util.Set;import java.util.stream.Collectors;public class ProblemMapper {    private ProblemMapper() {    }    public static Problem toEntity(ProblemRequestDTO dto, Set<Tag> tags) {        return Problem.builder()                .leetcodeId(dto.getLeetcodeId())                .title(dto.getTitle())                .difficulty(dto.getDifficulty())                .url(dto.getUrl())                .tags(tags)                .build();    }    public static ProblemResponseDTO toResponse(Problem problem) {        Set<TagResponseDTO> tagResponses =                problem.getTags()                        .stream()                        .map(TagMapper::toResponse)                        .collect(Collectors.toSet());        return ProblemResponseDTO.builder()                .id(problem.getId())                .leetcodeId(problem.getLeetcodeId())                .title(problem.getTitle())                .difficulty(problem.getDifficulty())                .url(problem.getUrl())                .createdAt(problem.getCreatedAt())                .tags(tagResponses)                .build();    }}